        "privacy.title": "Privacy Policy",
        "privacy.updated": "Last updated: July 25, 2026.",
        "privacy.intro": "This policy explains what data Camilius collects, why, and how it's stored. The service is currently operated by Mihajlo Savovic as an individual (note: this will be updated if the service is registered as a company).",
        "privacy.contact.heading": "Contact",
        "privacy.contact.body": "For any privacy questions or data access/deletion requests, write to:",
        "privacy.dataCollected.heading": "What data we collect",
        "privacy.dataCollected.intro": "From the business owner, at registration:",
        "privacy.dataCollected.item1": "Business name and password (the password is stored hashed, never in readable form)",
        "privacy.dataCollected.item2": "A contact email address, used only for account recovery (password resets) and important account notices",
        "privacy.dataCollected.item3": "The working hours, price list, and FAQ you enter",
        "privacy.dataCollected.pageChat": "Every account also gets a hosted public page with a built-in chat and booking widget (and, optionally, the same widget embedded on a business's own site). When a visitor chats there, we store the message content and a random, anonymous session identifier generated by their own browser - not tied to any account of theirs - so the conversation has memory and, if they book an appointment, so it can be found again later. We don't require or collect a visitor's name, email, or phone number to use the chat.",
        "privacy.why.heading": "Why we collect this data",
        "privacy.why.body": "Solely to provide the service's function: automatically reading customer inquiries sent via your hosted page or an embedded widget, and generating and sending replies based on your business's data. Replies are always sent immediately, since a visitor is waiting live for an answer - there is no manual review step.",
        "privacy.sharing.heading": "Who we share data with",
        "privacy.sharing.intro": "We don't sell your data. To provide the service, certain data is processed through the following external services (data processors):",
        "privacy.sharing.openai": "the text of your customer's question and your business data (working hours, price list, FAQ) are sent to OpenAI to generate suggested replies.",
        "privacy.sharing.paddle": "used to process subscription payments; Paddle acts as merchant of record for all paid plans and handles your payment details directly - we never receive or store your card information.",
        "privacy.sharing.resend": "used to send account-related emails (e.g. password resets); processes your contact email address.",
        "privacy.sharing.railway": "our hosting provider; all data is physically stored on their servers (outside Serbia).",
        "privacy.storage.heading": "How we store data",
        "privacy.storage.body": "Dashboard login passwords are stored hashed (irreversibly). All communication with the site goes over HTTPS. That said, no system is 100% secure, and we can't guarantee absolute security.",
        "privacy.retention.heading": "How long we keep data",
        "privacy.retention.body": "We keep your data for as long as your account exists. If you'd like your account and all associated data deleted, send a request to the contact email above.",
        "privacy.cookies.heading": "Cookies",
        "privacy.cookies.body": "We use only one necessary (session) cookie to keep you logged into the dashboard. The public page's chat widget also stores a random, anonymous session identifier in your browser's local storage (not a cookie) so it can remember an ongoing conversation - this never leaves your browser except to key that same conversation on our server. We don't use cookies or local storage for marketing or tracking.",
        "privacy.rights.heading": "Your rights",
        "privacy.rights.body": "You have the right to request access to the data we hold about you, its correction, or its complete deletion. For any of these requests, write to the contact email above - we'll respond within a reasonable time.",
        "privacy.changes.heading": "Changes to this policy",
        "privacy.changes.body": "This policy may be updated from time to time. We'll try to notify users of significant changes via email.",

        "terms.title": "Terms of Service",
        "terms.updated": "Last updated: July 25, 2026.",
        "terms.intro": "By registering and using Camilius you accept these terms. The service is currently operated by Mihajlo Savovic as an individual. Questions:",
        "terms.whatItDoes.heading": "What the service does",
        "terms.whatItDoes.body": "Camilius builds your business a hosted public page with a built-in AI chat and booking widget (and, optionally, the same widget embedded on your own site). When a customer chats there, the AI automatically generates and sends a reply based on the business data you've entered, and can book, cancel, or reschedule an appointment directly in the conversation. Replies are sent immediately, since a visitor is waiting live for an answer - there is no manual review or approval step. You are solely responsible for the content of every reply sent from your account.",
        "terms.responsibilities.heading": "Your responsibilities",
        "terms.responsibilities.item1": "You're responsible for the accuracy of the data you enter (working hours, price list, FAQ) - AI replies rely on that data.",
        "terms.responsibilities.item2": "You're responsible for checking that AI-generated content is accurate and appropriate - we don't guarantee its accuracy. Replies are sent automatically and immediately, with no manual review step.",
        "terms.responsibilities.item3": "You agree not to use the service to send inappropriate, misleading, or unlawful content.",
        "terms.responsibilities.item4": "You're responsible for the security of your account credentials (email, password).",
        "terms.liability.heading": "Limitation of liability",
        "terms.liability.body": "The service is provided \"as is\", without a guarantee of uninterrupted operation or freedom from errors. We are not liable for damages arising from an inaccurate AI reply, service downtime, or data loss. You use the service at your own risk.",
        "terms.pricing.heading": "Pricing",
        "terms.pricing.body": "New accounts get a 14-day free trial with full access, starting from registration - nothing is charged during the trial, and we'll email a heads-up before it ends. Continuing after the trial requires choosing a paid plan (see the Subscription page for current tiers and pricing) and adding a payment method. Payments are processed by Paddle.com, our reseller of record, who also handles VAT/sales tax at checkout. You may cancel at any time using the \"Manage subscription\" link in the receipt email Paddle sent you, or by emailing us; canceling stops future charges. We reserve the right to change pricing for future billing periods, with advance notice to existing subscribers.",
        "terms.termination.heading": "Account termination",
        "terms.termination.body": "We reserve the right to suspend or terminate an account in case of misuse of the service (e.g. sending spam, attempting to bypass limits, unlawful use). You may request deletion of your account at any time.",
        "terms.changes.heading": "Changes to these terms",
        "terms.changes.body": "These terms may change from time to time. We'll try to announce significant changes via email. Continued use of the service after a change means you accept the new terms.",
        "terms.governingLaw.heading": "Governing law",
        "terms.governingLaw.body": "These terms are governed by the law of the Republic of Serbia.",
        "terms.seePrivacy": "For information about what data we collect and how we store it, see the",

