        "appSettings.support.faqTitle": "Preguntas frecuentes",
        "appSettings.support.faq1Q": "¿Por qué no apareció un mensaje de un cliente?",
        "appSettings.support.faq1A": "Asegúrate de que tu página esté publicada en Perfil y de que no hayas alcanzado tu límite diario de respuestas.",
        "appSettings.support.faq2Q": "¿Puedo ver lo que la IA le dijo a un cliente?",
        "appSettings.support.faq2A": "Sí - cada respuesta se envía al instante porque el cliente está conversando en vivo, y puedes revisar la conversación completa en cualquier momento en Conversaciones.",
        "appSettings.support.faq3Q": "¿Cómo sabe la IA qué responder?",
        "appSettings.support.faq3A": "Usa el horario de atención, la lista de precios y las preguntas frecuentes guardadas en tu Perfil, además de OpenAI, para redactar una respuesta adecuada a cada mensaje del cliente.",
        "appSettings.support.faq5Q": "¿Puede Camilius reservar citas automáticamente?",
        "appSettings.support.faq5A": "Sí, cuando un cliente pide un horario que coincide con tu disponibilidad, puede reservar la cita directamente y avisarte.",
        "appSettings.support.faq7Q": "¿Cómo funcionan los recordatorios de citas?",
        "appSettings.support.faq7A": "Actívalos en Configuración para recibir una notificación en la app un tiempo determinado antes de cada cita próxima.",
        "appSettings.support.faq8Q": "¿Puedo cambiar mi horario o precios más adelante?",
        "appSettings.support.faq8A": "Sí, actualízalos cuando quieras en Perfil. La IA siempre usa lo que esté guardado ahí para las nuevas respuestas.",
        "appSettings.support.faq9Q": "¿Qué incluye el plan Pro?",
        "appSettings.support.faq9A": "Pro desbloquea funciones como los recordatorios de citas. Consulta Suscripción en Configuración para ver el plan y el precio actuales.",
        "appSettings.support.faq10Q": "¿Se comparten mis datos con alguien?",
        "appSettings.support.faq10A": "Los mensajes de los clientes y la información de tu negocio se envían a OpenAI para generar las respuestas. Consulta la Política de privacidad para más detalles.",
        "appSettings.support.faq11Q": "¿Puedo eliminar mi cuenta y mis datos?",
        "appSettings.support.faq11A": "Sí, ve a Configuración y elige Eliminar cuenta. Esto elimina tu cuenta y conversaciones de forma permanente y no se puede deshacer.",
