        "landing.slider.example1.question": "Olá! Qual o horário de sábado e quanto custa um corte de cabelo feminino?",
        "landing.slider.example1.reply": "Aos sábados abrimos das 9:00 às 16:00.\nUm corte feminino custa 35$, inclui lavagem e escova.\nO sábado à tarde lota rápido, então vale reservar logo.",
        "landing.slider.example2.question": "Vocês fazem clareamento dental? Posso ir sem marcar ou preciso agendar?",
        "landing.slider.example2.reply": "O clareamento dental custa 120$.\nSempre agendamos com antecedência para reservar tempo suficiente, mas uma consulta rápida pode ser sem hora marcada.\nTenho um horário livre na quinta às 14:00, funciona pra você?",
        "landing.slider.example3.question": "A tela do meu iPhone 13 quebrou, quanto custa o conserto e quanto tempo leva?",
        "landing.slider.example3.reply": "A troca de tela do iPhone 13 custa 89$, com 6 meses de garantia na peça.\nGeralmente pronta no mesmo dia se você trouxer até as 14:00.\nSe a estrutura também estiver amassada, avaliamos isso à parte primeiro, para não haver surpresa no valor.",
        "landing.slider.example4.question": "A torneira da minha cozinha está vazando, alguém pode ir dar uma olhada esta semana?",
        "landing.slider.example4.reply": "Puxa, sinto muito!\nTemos horários livres na quarta e quinta à tarde — a visita com inspeção custa 25$.\nSe precisar de um vedante ou cartucho novo, orçamos isso à parte antes de mexer em qualquer coisa.",
        "landing.slider.example5.question": "Que horas é o check-in e vocês aceitam animais de estimação?",
        "landing.slider.example5.reply": "O check-in é a partir das 15:00 e o check-out até as 11:00.\nPets são bem-vindos — há uma pequena taxa de limpeza.\nSe avisar com antecedência, deixamos toalhas extras para eles.",
        "landing.slider.example6.question": "Quanto custa uma chamada de estratégia de uma hora e como faço para agendar?",
        "landing.slider.example6.reply": "Uma chamada de estratégia de uma hora custa 90$ e inclui um breve resumo por escrito depois.\nTenho um horário livre na terça ou quinta de manhã essa semana, algum funciona pra você?",
        "landing.slider.example7.question": "O vestido midi verde tem no tamanho M? Qual é a política de trocas?",
        "landing.slider.example7.reply": "Sim, o midi verde ainda tem no tamanho M!\nAs trocas são gratuitas em até 14 dias, desde que a etiqueta esteja presa.\nSó uma observação: peças ajustadas não têm devolução.",
        "landing.slider.example8.question": "Quanto custa uma manicure em gel, e preciso agendar com antecedência?",
        "landing.slider.example8.reply": "Uma manicure em gel custa 28$ e leva cerca de 45 minutos.\nOs fins de semana lotam com uns dois dias de antecedência, mas nos dias de semana geralmente conseguimos encaixar no mesmo dia.",
        "landing.slider.example9.question": "Qual o preço do plano mensal, e tudo bem se eu nunca treinei antes?",
        "landing.slider.example9.reply": "O plano mensal custa 80$ por 8 sessões.\nE sim — muitos dos nossos alunos começam do zero.\nSua primeira sessão é uma avaliação leve para o treinador montar um plano de acordo com seu nível real.",
        "landing.slider.example10.question": "Vocês têm disponibilidade para um casamento no dia 12 de setembro, e o que está incluso no pacote?",
        "landing.slider.example10.reply": "O dia 12 de setembro ainda está livre!\nO pacote padrão inclui 6 horas de cobertura e mais de 300 fotos editadas.\nAlém de uma galeria prévia na mesma semana, para você não esperar meses para ver algo.",

