        "landing.slider.example1.question": "Bonjour ! Quels sont vos horaires le samedi, et combien coûte une coupe femme ?",
        "landing.slider.example1.reply": "Nous sommes ouverts le samedi de 9:00 à 16:00.\nUne coupe femme coûte 35$, shampoing et brushing inclus.\nLes samedis après-midi partent vite, mieux vaut réserver rapidement.",
        "landing.slider.example2.question": "Faites-vous le blanchiment dentaire ? Puis-je venir sans rendez-vous ou dois-je en prendre un ?",
        "landing.slider.example2.reply": "Le blanchiment dentaire coûte 120$.\nNous le réservons toujours à l'avance pour prévoir assez de temps, mais une consultation rapide peut se faire sans rendez-vous.\nJ'ai un créneau libre jeudi à 14:00, ça vous convient ?",
        "landing.slider.example3.question": "L'écran de mon iPhone 13 est cassé, combien coûte la réparation et combien de temps ça prend ?",
        "landing.slider.example3.reply": "Le remplacement d'écran d'iPhone 13 coûte 89$, avec 6 mois de garantie sur la pièce.\nGénéralement prêt le jour même si déposé avant 14:00.\nSi le châssis est tordu aussi, on vérifie ça séparément d'abord pour éviter une mauvaise surprise sur le prix.",
        "landing.slider.example4.question": "Mon robinet de cuisine fuit, quelqu'un peut-il venir jeter un œil cette semaine ?",
        "landing.slider.example4.reply": "Désolé de l'apprendre !\nNous avons des créneaux mercredi et jeudi après-midi — le déplacement avec inspection coûte 25$.\nS'il faut un joint ou une cartouche neuve, on vous chiffre ça séparément avant de toucher à quoi que ce soit.",
        "landing.slider.example5.question": "À quelle heure est l'arrivée, et les animaux sont-ils acceptés ?",
        "landing.slider.example5.reply": "L'arrivée est possible à partir de 15:00, le départ avant 11:00.\nLes animaux sont les bienvenus — de petits frais de ménage s'appliquent.\nSi vous nous prévenez à l'avance, on laissera des serviettes en plus pour eux.",
        "landing.slider.example6.question": "Combien coûte un appel stratégie d'une heure, et comment je réserve ?",
        "landing.slider.example6.reply": "Un appel stratégie d'une heure coûte 90$ et inclut un court résumé écrit ensuite.\nJ'ai un créneau libre mardi ou jeudi matin cette semaine, l'un des deux vous convient ?",
        "landing.slider.example7.question": "La robe midi verte existe-t-elle en taille M, et quelle est votre politique de retour ?",
        "landing.slider.example7.reply": "Oui, la robe midi verte est encore disponible en taille M !\nLes retours sont gratuits sous 14 jours tant que l'étiquette est encore attachée.\nÀ noter que les pièces retouchées ne sont pas reprises.",
        "landing.slider.example8.question": "Combien coûte une manucure au gel, et faut-il réserver à l'avance ?",
        "landing.slider.example8.reply": "Une manucure au gel coûte 28$ et prend environ 45 minutes.\nLe week-end se réserve quelques jours à l'avance, mais en semaine on peut généralement vous caser le jour même.",
        "landing.slider.example9.question": "Quel est le prix de l'abonnement mensuel, et est-ce grave si je n'ai jamais fait de sport ?",
        "landing.slider.example9.reply": "L'abonnement mensuel coûte 80$ pour 8 séances.\nEt oui — beaucoup de nos membres débutent de zéro.\nVotre première séance est une évaluation en douceur pour que le coach construise un programme adapté à votre niveau réel.",
        "landing.slider.example10.question": "Avez-vous une disponibilité pour un mariage le 12 septembre, et qu'est-ce qui est inclus dans votre forfait ?",
        "landing.slider.example10.reply": "Le 12 septembre est encore libre !\nLe forfait standard comprend 6 heures de couverture et plus de 300 photos retouchées.\nPlus une galerie d'aperçu dans la même semaine pour ne pas attendre des mois avant de voir quoi que ce soit.",

