        "appSettings.support.faqTitle": "Questions fréquentes",
        "appSettings.support.faq1Q": "Pourquoi le message d'un client n'est-il pas apparu ?",
        "appSettings.support.faq1A": "Assurez-vous que votre page est publiée dans Profil, et que votre limite quotidienne de réponses n'a pas été atteinte.",
        "appSettings.support.faq2Q": "Puis-je voir ce que l'IA a dit à un client ?",
        "appSettings.support.faq2A": "Oui - chaque réponse est envoyée instantanément puisque le client discute en direct, et vous pouvez consulter la conversation complète à tout moment dans Conversations.",
        "appSettings.support.faq3Q": "Comment l'IA sait-elle quoi répondre ?",
        "appSettings.support.faq3A": "Elle utilise les horaires, la liste de prix et la FAQ enregistrés dans votre Profil, ainsi qu'OpenAI, pour rédiger une réponse adaptée à chaque message client.",
        "appSettings.support.faq5Q": "Camilius peut-il réserver des rendez-vous automatiquement ?",
