        "appSettings.support.faq7Q": "Comment fonctionnent les rappels de rendez-vous ?",
        "appSettings.support.faq7A": "Activez-les dans Paramètres pour recevoir une notification dans l'app un délai déterminé avant chaque rendez-vous à venir.",
        "appSettings.support.faq8Q": "Puis-je changer mes horaires ou mes prix plus tard ?",
        "appSettings.support.faq8A": "Oui, modifiez-les à tout moment dans Profil. L'IA utilise toujours ce qui y est enregistré pour les nouvelles réponses.",
        "appSettings.support.faq9Q": "Qu'est-ce qui est inclus dans le plan Pro ?",
        "appSettings.support.faq9A": "Pro débloque des fonctionnalités comme les rappels de rendez-vous. Consultez Abonnement dans Paramètres pour le plan et le tarif actuels.",
        "appSettings.support.faq10Q": "Mes données sont-elles partagées avec quelqu'un ?",
        "appSettings.support.faq10A": "Les messages des clients et les informations de votre entreprise sont envoyés à OpenAI pour générer les réponses. Consultez la Politique de confidentialité pour plus de détails.",
        "appSettings.support.faq11Q": "Puis-je supprimer mon compte et mes données ?",
