        "landing.slider.time.now": "Gerade eben",
        "landing.slider.time.m2": "Vor 2 Min.",
        "landing.slider.time.m5": "Vor 5 Min.",
        "landing.slider.time.m12": "Vor 12 Min.",
        "landing.slider.time.h1": "Vor 1 Std.",

        "landing.slider.example1.question": "Hallo! Wie sind eure Öffnungszeiten am Samstag, und was kostet ein Damenhaarschnitt?",
        "landing.slider.example1.reply": "Samstags haben wir von 9:00 bis 16:00 Uhr geöffnet.\nEin Damenhaarschnitt kostet 35$ inklusive Waschen und Föhnen.\nSamstagnachmittage sind schnell ausgebucht, also am besten bald einen Termin sichern.",
        "landing.slider.example2.question": "Bietet ihr Zahnaufhellung an? Kann ich einfach vorbeikommen oder brauche ich einen Termin?",
        "landing.slider.example2.reply": "Zahnaufhellung kostet 120$.\nDafür buchen wir immer im Voraus, damit genug Zeit eingeplant ist, ein kurzer Check kann aber spontan erfolgen.\nDonnerstag um 14:00 Uhr wäre noch ein Termin frei, passt das?",
        "landing.slider.example3.question": "Mein iPhone-13-Display ist gesprungen — was kostet die Reparatur und wie lange dauert sie?",
        "landing.slider.example3.reply": "Ein Displaytausch beim iPhone 13 kostet 89$ mit 6 Monaten Garantie auf das Teil.\nMeist noch am selben Tag fertig, wenn du es vor 14:00 Uhr vorbeibringst.\nFalls das Gehäuse auch verbogen ist, prüfen wir das vorher separat, damit es beim Preis keine Überraschung gibt.",
        "landing.slider.example4.question": "Mein Küchenhahn tropft — kann diese Woche jemand vorbeikommen und schauen?",
        "landing.slider.example4.reply": "Das tut mir leid!\nWir haben Mittwoch- und Donnerstagnachmittag noch Termine frei — Anfahrt plus Begutachtung kostet 25$.\nFalls eine neue Dichtung oder Kartusche nötig ist, sprechen wir den Preis dafür vorher separat ab.",
        "landing.slider.example5.question": "Um wie viel Uhr ist der Check-in, und sind Haustiere erlaubt?",
        "landing.slider.example5.reply": "Check-in ist ab 15:00 Uhr, Check-out bis 11:00 Uhr.\nHaustiere sind willkommen — dafür fällt eine kleine Reinigungsgebühr an.\nWenn du uns vorher Bescheid gibst, legen wir zusätzliche Handtücher für sie bereit.",
        "landing.slider.example6.question": "Was kostet ein einstündiges Strategiegespräch, und wie buche ich es?",
        "landing.slider.example6.reply": "Ein einstündiges Strategiegespräch kostet 90$ und beinhaltet danach eine kurze schriftliche Zusammenfassung.\nDiese Woche wäre Dienstag- oder Donnerstagvormittag noch ein Termin frei, passt dir einer davon?",
        "landing.slider.example7.question": "Gibt es das grüne Midikleid in Größe M, und wie ist eure Rückgaberegelung?",
        "landing.slider.example7.reply": "Ja, das grüne Midikleid ist noch in Größe M vorrätig!\nRückgaben sind innerhalb von 14 Tagen kostenlos möglich, solange das Etikett noch dran ist.\nGeänderte Teile sind allerdings vom Umtausch ausgeschlossen.",
        "landing.slider.example8.question": "Was kostet eine Gel-Maniküre, und muss ich vorher einen Termin buchen?",
        "landing.slider.example8.reply": "Eine Gel-Maniküre kostet 28$ und dauert etwa 45 Minuten.\nWochenenden sind meist schon ein paar Tage vorher ausgebucht, unter der Woche bekommen wir dich aber meist noch am selben Tag unter.",
        "landing.slider.example9.question": "Was kostet das Monatsabo, und ist es okay, wenn ich noch nie trainiert habe?",
        "landing.slider.example9.reply": "Das Monatsabo kostet 80$ für 8 Einheiten.\nUnd ja — viele unserer Mitglieder fangen bei null an.\nDie erste Einheit ist ein sanfter Check, damit der Trainer einen Plan passend zu deinem tatsächlichen Level erstellen kann.",
        "landing.slider.example10.question": "Habt ihr am 12. September für eine Hochzeit noch etwas frei, und was ist im Paket enthalten?",
        "landing.slider.example10.reply": "Der 12. September ist noch frei!\nDas Standardpaket umfasst 6 Stunden Begleitung und über 300 bearbeitete Fotos.\nDazu eine Vorschau-Galerie noch in derselben Woche, damit ihr nicht monatelang auf erste Bilder warten müsst.",

