        "appSettings.support.faq1Q": "Warum ist eine Kundennachricht nicht erschienen?",
        "appSettings.support.faq1A": "Stelle sicher, dass deine Seite in Profil veröffentlicht ist und dein tägliches Antwortlimit nicht erreicht wurde.",
        "appSettings.support.faq2Q": "Kann ich sehen, was die KI einem Kunden gesagt hat?",
        "appSettings.support.faq2A": "Ja - jede Antwort wird sofort gesendet, da der Kunde live chattet, und du kannst das vollständige Gespräch jederzeit in Konversationen einsehen.",
        "appSettings.support.faq3Q": "Woher weiß die KI, was sie antworten soll?",
        "appSettings.support.faq3A": "Sie nutzt die Öffnungszeiten, die Preisliste und die FAQ-Antworten aus deinem Profil sowie OpenAI, um für jede Kundennachricht eine passende Antwort zu verfassen.",
        "appSettings.support.faq5Q": "Kann Camilius Termine automatisch buchen?",
        "appSettings.support.faq5A": "Ja - wenn ein Kunde eine Zeit anfragt, die zu deinen Öffnungszeiten passt, kann der Termin direkt gebucht und du benachrichtigt werden.",
        "appSettings.support.faq7Q": "Wie funktionieren Terminerinnerungen?",
        "appSettings.support.faq7A": "Aktiviere sie in Einstellungen, um eine App-Benachrichtigung eine festgelegte Zeit vor jedem bevorstehenden Termin zu erhalten.",
        "appSettings.support.faq8Q": "Kann ich meine Öffnungszeiten oder Preise später ändern?",
        "appSettings.support.faq8A": "Ja, aktualisiere sie jederzeit im Profil. Die KI verwendet für neue Antworten immer das, was dort gespeichert ist.",
        "appSettings.support.faq9Q": "Was ist im Pro-Plan enthalten?",
        "appSettings.support.faq9A": "Pro schaltet Funktionen wie Terminerinnerungen frei. Sieh dir Abo in den Einstellungen für den aktuellen Plan und Preis an.",
        "appSettings.support.faq10Q": "Werden meine Daten mit jemandem geteilt?",
        "appSettings.support.faq10A": "Kundennachrichten und deine Unternehmensdaten werden zur Erstellung der Antworten an OpenAI gesendet. Details findest du in der Datenschutzerklärung.",
