        "landing.slider.time.now": "Proprio ora",
        "landing.slider.time.m2": "2 min fa",
        "landing.slider.time.m5": "5 min fa",
        "landing.slider.time.m12": "12 min fa",
        "landing.slider.time.h1": "1 ora fa",

        "landing.slider.example1.question": "Ciao! Che orari fate il sabato, e quanto costa un taglio da donna?",
        "landing.slider.example1.reply": "Il sabato siamo aperti dalle 9:00 alle 16:00.\nUn taglio da donna costa 35$, include shampoo e piega.\nIl sabato pomeriggio si riempie in fretta, quindi conviene prenotare presto.",
        "landing.slider.example2.question": "Fate lo sbiancamento dentale? Posso venire senza appuntamento o devo prenotare?",
        "landing.slider.example2.reply": "Lo sbiancamento dentale costa 120$.\nLo prenotiamo sempre in anticipo per riservare abbastanza tempo, ma per un controllo veloce si può venire senza appuntamento.\nHo un posto libero giovedì alle 14:00, ti va bene?",
        "landing.slider.example3.question": "Lo schermo del mio iPhone 13 si è rotto — quanto costa ripararlo e quanto tempo ci vuole?",
        "landing.slider.example3.reply": "La sostituzione dello schermo dell'iPhone 13 costa 89$, con 6 mesi di garanzia sul pezzo.\nDi solito pronta in giornata se lo porti entro le 14:00.\nSe anche il telaio è piegato, lo controlliamo a parte prima, così non ci sono sorprese sul prezzo.",
        "landing.slider.example4.question": "Il rubinetto della cucina perde — può venire qualcuno a dare un'occhiata questa settimana?",
        "landing.slider.example4.reply": "Mi dispiace!\nAbbiamo disponibilità mercoledì e giovedì pomeriggio — il sopralluogo con ispezione costa 25$.\nSe serve una nuova guarnizione o cartuccia, te la preventiviamo a parte prima di toccare nulla.",
        "landing.slider.example5.question": "A che ora è il check-in, e si possono portare animali?",
        "landing.slider.example5.reply": "Il check-in è dalle 15:00, il check-out entro le 11:00.\nGli animali sono benvenuti — si applica una piccola tassa di pulizia.\nSe ci avvisi in anticipo lasceremo asciugamani extra per loro.",
        "landing.slider.example6.question": "Quanto costa una call strategica di un'ora, e come si prenota?",
        "landing.slider.example6.reply": "Una call strategica di un'ora costa 90$ e include un breve riepilogo scritto in seguito.\nHo un posto libero martedì o giovedì mattina questa settimana, ti va bene uno dei due?",
        "landing.slider.example7.question": "Il vestito midi verde è disponibile in taglia M, e qual è la vostra politica di reso?",
        "landing.slider.example7.reply": "Sì, il midi verde è ancora disponibile in taglia M!\nI resi sono gratuiti entro 14 giorni, purché l'etichetta sia ancora attaccata.\nLe taglie modificate però non sono rimborsabili.",
        "landing.slider.example8.question": "Quanto costa una manicure gel, e devo prenotare in anticipo?",
        "landing.slider.example8.reply": "Una manicure gel costa 28$ e dura circa 45 minuti.\nIl weekend si prenota un paio di giorni prima, ma nei giorni feriali di solito riusciamo a trovarti posto lo stesso giorno.",
        "landing.slider.example9.question": "Quanto costa l'abbonamento mensile, e va bene se non mi sono mai allenato/a prima?",
        "landing.slider.example9.reply": "L'abbonamento mensile costa 80$ per 8 sessioni.\nE sì — molti dei nostri iscritti partono da zero.\nLa prima sessione è una valutazione leggera così l'allenatore può costruire un piano sul tuo livello reale.",
        "landing.slider.example10.question": "Avete disponibilità per un matrimonio il 12 settembre, e cosa include il vostro pacchetto?",
        "landing.slider.example10.reply": "Il 12 settembre è ancora libero!\nIl pacchetto standard include 6 ore di copertura e oltre 300 foto ritoccate.\nPiù una galleria di anteprima nella stessa settimana, così non aspetti mesi per vedere qualcosa.",

        "landing.nav.login": "Accedi",
        "landing.nav.tryFree": "Prova gratis",
        "landing.nav.whoFor": "Per chi è pensato",
        "landing.hero.title1": "Un cliente ti scrive a mezzanotte.",
        "landing.hero.title2": "Camilius ha già risposto — e prenotato per martedì.",
        "landing.hero.subtitle1": "Camilius crea per la tua attività una pagina con una chat IA che risponde istantaneamente a ogni messaggio — in base a orari, prezzi e FAQ — e prenota l'appuntamento quando necessario.",
        "landing.hero.subtitle2": "Inviato in pochi secondi, giorno e notte — nessun cliente aspetta.",
        "landing.hero.ctaFree": "Inizia gratis",
        "landing.hero.ctaTrial": "Prova gratis per 14 giorni",
        "landing.hero.finePrintBeta": "Gratis durante la beta · hai sempre il controllo di ciò che viene inviato",
        "landing.trust.reviewed": "Ogni risposta viene inviata automaticamente, nessuna revisione necessaria",
        "landing.trust.drafted": "Redatta in ~60 secondi",
        "landing.slider.sectionTitle": "Guardalo in azione",
        "landing.slider.customerQuestionLabel": "Domanda del cliente",
        "landing.slider.aiReplyLabel": "Risposta suggerita dall'IA",
        "landing.slider.caption": "Esempi reali, basati sulle informazioni sulla tua attività mostrate durante la registrazione.",
        "landing.howItWorks.title": "Come funziona",
