        "appSettings.support.faqTitle": "Domande frequenti",
        "appSettings.support.faq1Q": "Perché non è apparso un messaggio di un cliente?",
        "appSettings.support.faq1A": "Assicurati che la tua pagina sia pubblicata in Profilo e che il limite giornaliero di risposte non sia stato raggiunto.",
        "appSettings.support.faq2Q": "Posso vedere cosa l'IA ha detto a un cliente?",
        "appSettings.support.faq2A": "Sì - ogni risposta viene inviata istantaneamente poiché il cliente sta chattando dal vivo, e puoi rivedere l'intera conversazione in qualsiasi momento in Conversazioni.",
        "appSettings.support.faq3Q": "Come fa l'IA a sapere cosa rispondere?",
        "appSettings.support.faq3A": "Usa gli orari, il listino prezzi e le FAQ salvate nel tuo Profilo, oltre a OpenAI, per scrivere una risposta adatta a ogni messaggio del cliente.",
        "appSettings.support.faq5Q": "Camilius può prenotare appuntamenti automaticamente?",
        "appSettings.support.faq5A": "Sì - quando un cliente chiede un orario compatibile con la tua disponibilità, può prenotare direttamente l'appuntamento e avvisarti.",
        "appSettings.support.faq7Q": "Come funzionano i promemoria degli appuntamenti?",
        "appSettings.support.faq7A": "Attivali in Impostazioni per ricevere una notifica nell'app un tempo prestabilito prima di ogni appuntamento imminente.",
        "appSettings.support.faq8Q": "Posso cambiare orari o prezzi in seguito?",
        "appSettings.support.faq8A": "Sì, aggiornali quando vuoi nel Profilo. L'IA usa sempre ciò che è salvato lì per le nuove risposte.",
        "appSettings.support.faq9Q": "Cosa include il piano Pro?",
        "appSettings.support.faq9A": "Pro sblocca funzioni come i promemoria degli appuntamenti. Controlla Abbonamento in Impostazioni per il piano e il prezzo attuali.",
        "appSettings.support.faq10Q": "I miei dati vengono condivisi con qualcuno?",
        "appSettings.support.faq10A": "I messaggi dei clienti e le informazioni della tua attività vengono inviati a OpenAI per generare le risposte. Consulta l'Informativa sulla privacy per i dettagli.",
