        "landing.slider.example1.question": "Привет! А в какое время вы работаете по субботам, и сколько стоит женская стрижка?",
        "landing.slider.example1.reply": "По субботам мы открыты с 9:00 до 16:00.\nЖенская стрижка стоит 35$, включает мытьё и укладку.\nСубботние вечера быстро заполняются, так что лучше записаться заранее.",
        "landing.slider.example2.question": "Вы делаете отбеливание зубов? Можно просто прийти или нужна запись?",
        "landing.slider.example2.reply": "Отбеливание зубов стоит 120$.\nНа эту процедуру мы всегда записываем заранее, чтобы выделить достаточно времени, а вот на быстрый осмотр можно и без записи.\nЕсть свободное время в четверг в 14:00, подойдёт?",
        "landing.slider.example3.question": "У меня разбит экран на iPhone 13 — сколько стоит ремонт и сколько это займёт?",
        "landing.slider.example3.reply": "Замена экрана iPhone 13 стоит 89$ с 6-месячной гарантией на деталь.\nОбычно готово в тот же день, если сдать до 14:00.\nЕсли корпус тоже погнут, мы сначала оценим это отдельно, чтобы цена не стала сюрпризом.",
        "landing.slider.example4.question": "У меня течёт кран на кухне — может кто-нибудь приехать посмотреть на этой неделе?",
        "landing.slider.example4.reply": "Очень жаль это слышать!\nУ нас есть свободное время в среду и четверг после обеда — выезд с осмотром стоит 25$.\nЕсли понадобится новая прокладка или картридж, мы озвучим их стоимость отдельно, прежде чем что-либо трогать.",
        "landing.slider.example5.question": "Во сколько заезд, и можно ли с домашними животными?",
        "landing.slider.example5.reply": "Заезд с 15:00, выезд до 11:00.\nС животными можно — взимается небольшой сбор за уборку.\nЕсли предупредите заранее, мы оставим для них дополнительные полотенца.",
        "landing.slider.example6.question": "Сколько стоит часовая стратегическая консультация и как записаться?",
        "landing.slider.example6.reply": "Часовая стратегическая консультация стоит 90$ и включает краткое письменное резюме после звонка.\nНа этой неделе есть свободное время во вторник или четверг утром — какой день вам подходит?",
        "landing.slider.example7.question": "Есть ли зелёное миди-платье в размере M, и какая у вас политика возврата?",
        "landing.slider.example7.reply": "Да, зелёное платье-миди ещё есть в размере M!\nВозврат бесплатный в течение 14 дней, если бирка не снята.\nНо изменённые изделия возврату не подлежат.",
        "landing.slider.example8.question": "Сколько стоит гель-маникюр и нужно ли записываться заранее?",
        "landing.slider.example8.reply": "Гель-маникюр стоит 28$ и занимает около 45 минут.\nНа выходные записываются за пару дней, а в будни мы обычно можем принять вас в тот же день.",
        "landing.slider.example9.question": "Сколько стоит месячный абонемент, и ничего, если я никогда раньше не тренировался(-ась)?",
        "landing.slider.example9.reply": "Месячный абонемент стоит 80$ за 8 занятий.\nИ да — многие наши участники начинают с нуля.\nПервое занятие — это лёгкая оценка уровня, чтобы тренер составил план именно под вас.",
        "landing.slider.example10.question": "Есть ли у вас свободная дата на свадьбу 12 сентября, и что входит в ваш пакет услуг?",
        "landing.slider.example10.reply": "12 сентября пока свободно!\nСтандартный пакет включает 6 часов съёмки и более 300 обработанных фото.\nПлюс превью-галерею уже на этой неделе, чтобы не ждать месяцами первых кадров.",

