        "privacy.title": "Politika privatnosti",
        "privacy.updated": "Poslednje ažuriranje: 25. jul 2026.",
        "privacy.intro": "Ova politika objašnjava koje podatke Camilius prikuplja, zašto, i kako se čuvaju. Uslugu trenutno vodi Mihajlo Savović kao fizičko lice (napomena: ovo će biti ažurirano ako usluga bude registrovana kao kompanija).",
        "privacy.contact.heading": "Kontakt",
        "privacy.contact.body": "Za sva pitanja o privatnosti ili zahteve za pristup/brisanje podataka, pišite na:",
        "privacy.dataCollected.heading": "Koje podatke prikupljamo",
        "privacy.dataCollected.intro": "Od vlasnika biznisa, prilikom registracije:",
        "privacy.dataCollected.item1": "Naziv biznisa i lozinka (lozinka se čuva heširana, nikada u čitljivom obliku)",
        "privacy.dataCollected.item2": "Kontakt imejl adresa, koja se koristi samo za oporavak naloga (resetovanje lozinke) i važna obaveštenja o nalogu",
        "privacy.dataCollected.item3": "Radno vreme, cenovnik i česta pitanja koje unesete",
        "privacy.dataCollected.pageChat": "Svaki nalog takođe dobija hostovanu javnu stranicu sa ugrađenim chat i booking widget-om (i, opciono, isti widget ugrađen na sopstvenom sajtu biznisa). Kada posetilac čatuje tamo, čuvamo sadržaj poruke i nasumični, anonimni identifikator sesije koji generiše njegov sopstveni pregledač - nije povezan ni sa jednim njegovim nalogom - kako bi razgovor imao memoriju, a ako zakaže termin, kako bi mogao ponovo da se pronađe kasnije. Ne zahtevamo niti prikupljamo ime, imejl ili broj telefona posetioca da bi koristio chat.",
        "privacy.why.heading": "Zašto prikupljamo ove podatke",
        "privacy.why.body": "Isključivo radi pružanja funkcije servisa: automatskog čitanja upita klijenata poslatih preko tvoje hostovane stranice ili ugrađenog vidžeta, i generisanja i slanja odgovora na osnovu podataka tvog biznisa. Odgovori se uvek šalju odmah, pošto posetilac čeka uživo - ne postoji korak ručne provere.",
        "privacy.sharing.heading": "Sa kim delimo podatke",
        "privacy.sharing.intro": "Ne prodajemo vaše podatke. Radi pružanja usluge, određeni podaci se obrađuju kroz sledeće spoljne servise (obrađivači podataka):",
        "privacy.sharing.openai": "tekst pitanja vaše mušterije i podaci vašeg biznisa (radno vreme, cenovnik, česta pitanja) šalju se OpenAI-ju radi generisanja predloženih odgovora.",
        "privacy.sharing.paddle": "koristi se za obradu pretplata; Paddle nastupa kao prodavac (merchant of record) za sve plaćene planove i direktno rukuje vašim podacima o plaćanju - mi nikada ne primamo niti čuvamo podatke o vašoj kartici.",
        "privacy.sharing.resend": "koristi se za slanje imejlova vezanih za nalog (npr. resetovanje lozinke); obrađuje vašu kontakt imejl adresu.",
        "privacy.sharing.railway": "naš hosting provajder; svi podaci se fizički čuvaju na njihovim serverima (van Srbije).",
        "privacy.storage.heading": "Kako čuvamo podatke",
        "privacy.storage.body": "Lozinke za prijavu na panel se čuvaju heširane (nepovratno). Sva komunikacija sa sajtom ide preko HTTPS-a. Ipak, nijedan sistem nije 100% bezbedan i ne možemo garantovati apsolutnu bezbednost.",
        "privacy.retention.heading": "Koliko dugo čuvamo podatke",
        "privacy.retention.body": "Čuvamo vaše podatke sve dok vaš nalog postoji. Ako želite da vaš nalog i svi povezani podaci budu obrisani, pošaljite zahtev na gore navedeni kontakt imejl.",
        "privacy.cookies.heading": "Kolačići",
        "privacy.cookies.body": "Koristimo samo jedan neophodan (sesijski) kolačić da biste ostali prijavljeni na kontrolnu tablu. Chat widget na javnoj stranici takođe čuva nasumični, anonimni identifikator sesije u lokalnoj memoriji vašeg pregledača (local storage, ne kolačić) kako bi mogao da zapamti razgovor u toku - ovo nikada ne napušta vaš pregledač osim da poveže taj isti razgovor na našem serveru. Ne koristimo kolačiće ni lokalnu memoriju za marketing ili praćenje.",
        "privacy.rights.heading": "Vaša prava",
        "privacy.rights.body": "Imate pravo da zatražite pristup podacima koje čuvamo o vama, njihovu ispravku, ili potpuno brisanje. Za bilo koji od ovih zahteva, pišite na gore navedeni kontakt imejl - odgovorićemo u razumnom roku.",
        "privacy.changes.heading": "Izmene ove politike",
        "privacy.changes.body": "Ova politika se može povremeno ažurirati. Trudićemo se da obavestimo korisnike o značajnim izmenama putem imejla.",

        "terms.title": "Uslovi korišćenja",
        "terms.updated": "Poslednje ažuriranje: 25. jul 2026.",
        "terms.intro": "Registracijom i korišćenjem Camilius-a prihvatate ove uslove. Uslugu trenutno vodi Mihajlo Savović kao fizičko lice. Pitanja:",
        "terms.whatItDoes.heading": "Šta usluga radi",
        "terms.whatItDoes.body": "Camilius pravi za tvoj biznis hostovanu javnu stranicu sa ugrađenim AI ćaskanjem i vidžetom za zakazivanje (i, opciono, istim vidžetom ugrađenim na tvom sopstvenom sajtu). Kada klijent tamo ćaska, AI automatski generiše i šalje odgovor na osnovu podataka o biznisu koje si uneo, i može da zakaže, otkaže ili pomeri termin direktno u razgovoru. Odgovori se šalju odmah, pošto posetilac čeka uživo - ne postoji korak ručne provere ili odobrenja. Isključivo si odgovoran za sadržaj svakog odgovora poslatog sa tvog naloga.",
        "terms.responsibilities.heading": "Vaše odgovornosti",
        "terms.responsibilities.item1": "Odgovorni ste za tačnost podataka koje unosite (radno vreme, cenovnik, česta pitanja) - AI odgovori zavise od tih podataka.",
        "terms.responsibilities.item2": "Odgovoran si za proveru da li je sadržaj koji generiše AI tačan i primeren - ne garantujemo njegovu tačnost. Odgovori se šalju automatski i odmah, bez koraka ručne provere.",
        "terms.responsibilities.item3": "Slažete se da nećete koristiti uslugu za slanje neprikladnog, obmanjujućeg ili nezakonitog sadržaja.",
        "terms.responsibilities.item4": "Odgovoran si za bezbednost kredencijala svog naloga (imejl, lozinka).",
        "terms.liability.heading": "Ograničenje odgovornosti",
        "terms.liability.body": "Usluga se pruža \"kao što jeste\", bez garancije neprekidnog rada ili odsustva grešaka. Nismo odgovorni za štetu nastalu usled netačnog AI odgovora, zastoja u radu usluge, ili gubitka podataka. Uslugu koristite na sopstveni rizik.",
        "terms.pricing.heading": "Cene",
        "terms.pricing.body": "Novi nalozi dobijaju besplatan probni period od 14 dana sa punim pristupom, počevši od registracije - ništa se ne naplaćuje tokom probnog perioda, a poslaćemo vam podsetnik pre nego što se završi. Za nastavak nakon probnog perioda potrebno je da izaberete plaćeni plan (pogledajte stranicu Pretplata za trenutne pakete i cene) i dodate način plaćanja. Plaćanja obrađuje Paddle.com, naš preprodavac (reseller of record), koji takođe obračunava PDV/porez na promet prilikom naplate. Možete otkazati u bilo kom trenutku preko linka \"Upravljanje pretplatom\" u mejlu sa računom koji vam je poslao Paddle, ili tako što ćete nam poslati mejl; otkazivanje zaustavlja buduće naplate. Zadržavamo pravo da promenimo cene za buduće periode naplate, uz prethodno obaveštenje postojećih pretplatnika.",
        "terms.termination.heading": "Ukidanje naloga",
        "terms.termination.body": "Zadržavamo pravo da suspendujemo ili ukinemo nalog u slučaju zloupotrebe usluge (npr. slanje spama, pokušaj zaobilaženja ograničenja, nezakonita upotreba). Možete zatražiti brisanje svog naloga u bilo kom trenutku.",
        "terms.changes.heading": "Izmene ovih uslova",
        "terms.changes.body": "Ovi uslovi se mogu povremeno menjati. Trudićemo se da najavimo značajne izmene putem imejla. Nastavljeno korišćenje usluge nakon izmene znači da prihvatate nove uslove.",
        "terms.governingLaw.heading": "Merodavno pravo",
        "terms.governingLaw.body": "Ovi uslovi su regulisani zakonom Republike Srbije.",
        "terms.seePrivacy": "Za informacije o tome koje podatke prikupljamo i kako ih čuvamo, pogledajte",

