        "landing.slider.time.now": "Az önce",
        "landing.slider.time.m2": "2 dk önce",
        "landing.slider.time.m5": "5 dk önce",
        "landing.slider.time.m12": "12 dk önce",
        "landing.slider.time.h1": "1 sa önce",

        "landing.slider.example1.question": "Merhaba! Cumartesi çalışma saatleriniz nedir, kadın saç kesimi ne kadar?",
        "landing.slider.example1.reply": "Cumartesi günleri 9:00-16:00 arası açığız.\nKadın saç kesimi 35$ olup yıkama ve fön dahildir.\nCumartesi öğleden sonraları hızlı doluyor, bu yüzden erken randevu almak iyi olur.",
        "landing.slider.example2.question": "Diş beyazlatma yapıyor musunuz? Randevusuz gelebilir miyim, yoksa randevu almam mı gerekiyor?",
        "landing.slider.example2.reply": "Diş beyazlatma 120$'dur.\nBunun için her zaman önceden randevu alırız ki yeterli süre ayırabilelim, ama hızlı bir kontrol için randevusuz da gelebilirsiniz.\nPerşembe saat 14:00'te boş bir yerim var, uygun mu?",
        "landing.slider.example3.question": "iPhone 13'ümün ekranı kırıldı, tamiri ne kadar tutar ve ne kadar sürer?",
        "landing.slider.example3.reply": "iPhone 13 ekran değişimi, parça için 6 ay garantili olarak 89$'dur.\nSaat 14:00'ten önce bırakırsanız genelde aynı gün hazır olur.\nKasa da eğilmişse fiyatta sürpriz olmaması için önce onu ayrıca kontrol ederiz.",
        "landing.slider.example4.question": "Mutfak muslugum damlıyor, bu hafta birisi gelip bakabilir mi?",
        "landing.slider.example4.reply": "Bunu duyduğuma üzüldüm!\nÇarşamba ve perşembe öğleden sonra müsaitliğimiz var — ziyaret ve inceleme 25$'dur.\nYeni bir conta veya kartuş gerekirse hiçbir şeye dokunmadan önce ayrıca fiyat veririz.",
        "landing.slider.example5.question": "Check-in saat kaçta, ve evcil hayvana izin veriyor musunuz?",
        "landing.slider.example5.reply": "Check-in saat 15:00'ten itibaren, check-out saat 11:00'e kadar.\nEvcil hayvanlar kabul ediliyor — küçük bir temizlik ücreti uygulanır.\nÖnceden haber verirseniz onlar için fazladan havlu da hazırlarız.",
        "landing.slider.example6.question": "Bir saatlik strateji görüşmesi ne kadar, ve nasıl randevu alabilirim?",
        "landing.slider.example6.reply": "Bir saatlik strateji görüşmesi 90$ olup sonrasında kısa yazılı bir özet de içerir.\nBu hafta salı veya perşembe sabahı boş bir saatim var, hangisi size uyar?",
        "landing.slider.example7.question": "Yeşil midi elbise M beden var mı, ve iade politikanız nedir?",
        "landing.slider.example7.reply": "Evet, yeşil midi elbise M bedende hâlâ mevcut!\nEtiketi üzerinde olduğu sürece 14 gün içinde iade ücretsizdir.\nAncak üzerinde değişiklik yapılan ürünler iade edilemez.",
        "landing.slider.example8.question": "Jel manikür ne kadar, ve önceden randevu almam gerekiyor mu?",
        "landing.slider.example8.reply": "Jel manikür 28$ olup yaklaşık 45 dakika sürer.\nHafta sonları birkaç gün önceden dolar, ama hafta içi genellikle aynı gün için yer bulabiliyoruz.",
        "landing.slider.example9.question": "Aylık paketin fiyatı nedir, ve daha önce hiç antrenman yapmadıysam sorun olur mu?",
        "landing.slider.example9.reply": "Aylık paket 8 seans için 80$'dur.\nVe evet — üyelerimizin çoğu sıfırdan başlıyor.\nİlk seans, koçun gerçek seviyenize uygun bir program oluşturabilmesi için hafif bir değerlendirmedir.",
        "landing.slider.example10.question": "12 Eylül'de bir düğün için müsaitliğiniz var mı, ve paketinize neler dahil?",
        "landing.slider.example10.reply": "12 Eylül hâlâ müsait!\nStandart paket 6 saatlik çekim ve 300'den fazla düzenlenmiş fotoğraf içerir.\nAyrıca aylarca beklemeden görebilmeniz için aynı hafta içinde bir ön izleme galerisi de sunuyoruz.",

